const crypto = require('crypto');

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `WF03 expected exactly one form submission, received ${items.length}`,
  );
}

const item = items[0];
const input = item.json ?? {};
const binary = item.binary ?? {};

const BUSINESS_FIELDS = [
  'company_identifier_country',
  'company_identifier_type',
  'company_identifier_value',
  'legal_name',
  'primary_contact_first_name',
  'primary_contact_last_name',
  'primary_contact_email',
  'primary_contact_phone',
];

const FIELD_LIMITS = {
  company_identifier_country: 8,
  company_identifier_type: 64,
  company_identifier_value: 128,
  legal_name: 256,
  primary_contact_first_name: 128,
  primary_contact_last_name: 128,
  primary_contact_email: 320,
  primary_contact_phone: 64,
};

const ALLOWED_TOP_LEVEL_FIELDS = new Set([
  ...BUSINESS_FIELDS,
  'submittedAt',
  'formMode',
  'formQueryParameters',
]);

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function rejectSubmission(
  decision,
  errorCode,
) {
  return [
    {
      json: {
        workflow: 'WF03',

        intake_decision: decision,
        intake_valid: false,

        error_code: errorCode,

        // The public response will be identical for malformed
        // forms and invalid tokens.
        client_response_key:
          'invalid_or_expired_submission_link',
      },
    },
  ];
}

function normalizeCommonString(value) {
  if (value === null) {
    return null;
  }

  const normalized = value
    .normalize('NFKC')
    .replace(/\p{White_Space}+/gu, ' ')
    .trim();

  return normalized === ''
    ? null
    : normalized;
}

function normalizeCountry(value) {
  const normalized =
    normalizeCommonString(value);

  return normalized === null
    ? null
    : normalized.toUpperCase();
}

function normalizeIdentifierType(value) {
  const normalized =
    normalizeCommonString(value);

  return normalized === null
    ? null
    : normalized.toLowerCase();
}

function normalizeIdentifierValue(value) {
  const visibleValue =
    normalizeCommonString(value);

  if (visibleValue === null) {
    return {
      visible: null,
      normalized: null,
    };
  }

  const normalizedValue = visibleValue
    .normalize('NFKC')
    .toUpperCase()
    .replace(/\p{White_Space}+/gu, '')
    .replace(/[-./]/g, '');

  return {
    visible: visibleValue,
    normalized:
      normalizedValue === ''
        ? null
        : normalizedValue,
  };
}

function normalizeEmail(value) {
  const normalized =
    normalizeCommonString(value);

  return normalized === null
    ? null
    : normalized.toLowerCase();
}

function normalizePhone(value) {
  const normalized =
    normalizeCommonString(value);

  if (normalized === null) {
    return null;
  }

  return normalized
    .replace(/\p{White_Space}+/gu, '')
    .replace(/[()\-]/g, '');
}

// A form submission must be one flat JSON object.
if (!isPlainObject(input)) {
  return rejectSubmission(
    'invalid_form',
    'form_payload_not_object',
  );
}

// Uploaded files are not accepted in this form.
if (Object.keys(binary).length > 0) {
  return rejectSubmission(
    'invalid_form',
    'file_upload_not_allowed',
  );
}

// Reject unexpected fields before token hashing
// or any database operation.
const unknownFields = Object.keys(input)
  .filter(
    (fieldName) =>
      !ALLOWED_TOP_LEVEL_FIELDS.has(fieldName),
  );

if (unknownFields.length > 0) {
  return rejectSubmission(
    'invalid_form',
    'unknown_form_fields',
  );
}

const submittedData = {};

for (const fieldName of BUSINESS_FIELDS) {
  const value =
    input[fieldName] === undefined
      ? null
      : input[fieldName];

  if (
    value !== null &&
    typeof value !== 'string'
  ) {
    return rejectSubmission(
      'invalid_form',
      'business_field_not_string',
    );
  }

  if (
    typeof value === 'string' &&
    Array.from(value).length >
      FIELD_LIMITS[fieldName]
  ) {
    return rejectSubmission(
      'invalid_form',
      'business_field_too_long',
    );
  }

  submittedData[fieldName] = value;
}

// This is a logical payload-size check.
// The reverse proxy will later provide the hard HTTP limit.
const payloadSizeBytes = Buffer.byteLength(
  JSON.stringify(submittedData),
  'utf8',
);

if (payloadSizeBytes > 64 * 1024) {
  return rejectSubmission(
    'invalid_form',
    'form_payload_too_large',
  );
}

const queryParameters =
  input.formQueryParameters;

if (!isPlainObject(queryParameters)) {
  return rejectSubmission(
    'unauthorized',
    'token_missing',
  );
}

// Only the opaque token is accepted in the public URL.
const unknownQueryParameters =
  Object.keys(queryParameters)
    .filter(
      (parameterName) =>
        parameterName !== 'token',
    );

if (unknownQueryParameters.length > 0) {
  return rejectSubmission(
    'invalid_form',
    'unknown_query_parameters',
  );
}

const plainToken =
  queryParameters.token;

if (
  typeof plainToken !== 'string' ||
  plainToken.length === 0 ||
  plainToken.length > 128 ||
  !/^[A-Za-z0-9_-]+$/.test(plainToken)
) {
  return rejectSubmission(
    'unauthorized',
    'token_malformed',
  );
}

let tokenBytes;

try {
  tokenBytes = Buffer.from(
    plainToken,
    'base64url',
  );
} catch {
  return rejectSubmission(
    'unauthorized',
    'token_malformed',
  );
}

// Canonical comparison prevents Buffer.from()
// from silently accepting malformed Base64URL.
const canonicalToken =
  tokenBytes.toString('base64url');

if (
  tokenBytes.length !== 32 ||
  canonicalToken !== plainToken
) {
  return rejectSubmission(
    'unauthorized',
    'token_malformed',
  );
}

const tokenHashBase64 = crypto
  .createHash('sha256')
  .update(tokenBytes)
  .digest('base64');

const identifier =
  normalizeIdentifierValue(
    submittedData
      .company_identifier_value,
  );

const normalizedData = {
  company_identifier_country:
    normalizeCountry(
      submittedData
        .company_identifier_country,
    ),

  company_identifier_type:
    normalizeIdentifierType(
      submittedData
        .company_identifier_type,
    ),

  company_identifier_value:
    identifier.visible,

  company_identifier_value_normalized:
    identifier.normalized,

  legal_name:
    normalizeCommonString(
      submittedData.legal_name,
    ),

  primary_contact_first_name:
    normalizeCommonString(
      submittedData
        .primary_contact_first_name,
    ),

  primary_contact_last_name:
    normalizeCommonString(
      submittedData
        .primary_contact_last_name,
    ),

  primary_contact_email:
    normalizeEmail(
      submittedData
        .primary_contact_email,
    ),

  primary_contact_phone:
    normalizePhone(
      submittedData
        .primary_contact_phone,
    ),
};

// Do not spread the original input here.
// That would copy the plain token into the next node.
return [
  {
    json: {
      workflow: 'WF03',

      intake_decision:
        'ready_for_authorization',

      intake_valid: true,

      token_hash_base64:
        tokenHashBase64,

      submitted_data:
        submittedData,

      normalized_data:
        normalizedData,

      form_mode:
        typeof input.formMode === 'string'
          ? input.formMode
          : null,

      submitted_at:
        typeof input.submittedAt === 'string'
          ? input.submittedAt
          : null,
    },
  },
];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    `WF03 token consumption expected exactly one result, received ${items.length}`,
  );
}

const row = items[0].json ?? {};

const inputContext =
  row.input_context &&
  typeof row.input_context === 'object' &&
  !Array.isArray(row.input_context)
    ? row.input_context
    : {};

const consumeOutcome =
  typeof row.consume_outcome === 'string'
    ? row.consume_outcome.trim()
    : '';

const unauthorizedOutcomes = new Set([
  'invalid_token',
  'already_consumed',
  'revoked',
  'expired',
  'not_delivered',
  'invalid_case_state',
]);

if (consumeOutcome === 'created') {
  const submissionId =
    typeof row.created_submission_id === 'string'
      ? row.created_submission_id.trim()
      : '';

  const caseId =
    typeof row.onboarding_case_id === 'string'
      ? row.onboarding_case_id.trim()
      : '';

  const submissionSequence =
    Number(row.created_submission_sequence);

  if (
    submissionId === '' ||
    caseId === '' ||
    !Number.isInteger(submissionSequence) ||
    submissionSequence < 1
  ) {
    return [
      {
        json: {
          workflow: 'WF03',

          authorization_decision:
            'invalid_database_result',

          consume_outcome:
            consumeOutcome || null,

          error_code:
            'created_result_missing_identity',

          client_response_key:
            'technical_failure',
        },
      },
    ];
  }

  return [
    {
      json: {
        workflow: 'WF03',

        authorization_decision:
          'submission_created',

        consume_outcome:
          'created',

        case_id:
          caseId,

        submission_id:
          submissionId,

        submission_sequence:
          submissionSequence,

        submitted_at:
          inputContext.submitted_at ?? null,

        form_mode:
          inputContext.form_mode ?? null,
      },
    },
  ];
}

if (unauthorizedOutcomes.has(consumeOutcome)) {
  return [
    {
      json: {
        workflow: 'WF03',

        authorization_decision:
          'unauthorized',

        // Kept internally for routing and audit.
        // It must not be shown to the client.
        consume_outcome:
          consumeOutcome,

        case_id: null,
        submission_id: null,
        submission_sequence: null,

        client_response_key:
          'invalid_or_expired_submission_link',
      },
    },
  ];
}

return [
  {
    json: {
      workflow: 'WF03',

      authorization_decision:
        'invalid_database_result',

      consume_outcome:
        consumeOutcome || null,

      error_code:
        'unsupported_consume_outcome',

      client_response_key:
        'technical_failure',
    },
  },
];

