const items = $input.all();

function buildTechnicalFailure(errorCode) {
  return [
    {
      json: {
        workflow: 'WF03',

        validation_decision:
          'invalid_authoritative_context',

        error_code: errorCode,

        client_response_key:
          'technical_failure',
      },
    },
  ];
}

if (items.length !== 1) {
  return buildTechnicalFailure(
    'authoritative_context_item_count_invalid',
  );
}

const row = items[0].json ?? {};

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function isUuid(value) {
  return (
    typeof value === 'string' &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
      .test(value)
  );
}

function normalizeCommonString(value) {
  if (value === null) {
    return null;
  }

  if (typeof value !== 'string') {
    return null;
  }

  const normalized = value
    .normalize('NFKC')
    .replace(/\p{White_Space}+/gu, ' ')
    .trim();

  return normalized === ''
    ? null
    : normalized;
}

function normalizeCountry(value) {
  const normalized =
    normalizeCommonString(value);

  return normalized === null
    ? null
    : normalized.toUpperCase();
}

function normalizeIdentifierType(value) {
  const normalized =
    normalizeCommonString(value);

  return normalized === null
    ? null
    : normalized.toLowerCase();
}

function normalizeIdentifierValue(value) {
  const visible =
    normalizeCommonString(value);

  if (visible === null) {
    return {
      visible: null,
      normalized: null,
    };
  }

  const normalized = visible
    .normalize('NFKC')
    .toUpperCase()
    .replace(/\p{White_Space}+/gu, '')
    .replace(/[-./]/g, '');

  return {
    visible,
    normalized:
      normalized === ''
        ? null
        : normalized,
  };
}

function normalizeEmail(value) {
  const normalized =
    normalizeCommonString(value);

  return normalized === null
    ? null
    : normalized.toLowerCase();
}

function normalizePhone(value) {
  const normalized =
    normalizeCommonString(value);

  if (normalized === null) {
    return null;
  }

  return normalized
    .replace(/\p{White_Space}+/gu, '')
    .replace(/[()\-]/g, '');
}

const contextErrors = [];

if (!isUuid(row.case_id)) {
  contextErrors.push('case_id_invalid');
}

if (!isUuid(row.correlation_id)) {
  contextErrors.push(
    'correlation_id_invalid',
  );
}

if (!isUuid(row.submission_id)) {
  contextErrors.push(
    'submission_id_invalid',
  );
}

if (!isUuid(row.token_id)) {
  contextErrors.push('token_id_invalid');
}

if (!isUuid(row.collect_step_id)) {
  contextErrors.push(
    'collect_step_id_invalid',
  );
}

if (!isUuid(row.validate_step_id)) {
  contextErrors.push(
    'validate_step_id_invalid',
  );
}

const submissionSequence =
  Number(row.submission_sequence);

if (
  !Number.isInteger(submissionSequence) ||
  submissionSequence < 1
) {
  contextErrors.push(
    'submission_sequence_invalid',
  );
}

if (row.case_state !== 'data_received') {
  contextErrors.push(
    'case_state_not_data_received',
  );
}

if (row.client_id !== null) {
  contextErrors.push(
    'case_client_already_assigned',
  );
}

if (row.accepted_submission_id !== null) {
  contextErrors.push(
    'case_submission_already_accepted',
  );
}

if (
  row.validation_status !== 'pending'
) {
  contextErrors.push(
    'submission_not_pending',
  );
}

if (
  !Array.isArray(row.validation_errors) ||
  row.validation_errors.length !== 0
) {
  contextErrors.push(
    'submission_errors_not_empty',
  );
}

if (row.token_status !== 'consumed') {
  contextErrors.push(
    'token_not_consumed',
  );
}

if (
  typeof row.token_consumed_at !== 'string' ||
  row.token_consumed_at.trim() === ''
) {
  contextErrors.push(
    'token_consumed_at_missing',
  );
}

if (
  row.collect_step_status !==
  'in_progress'
) {
  contextErrors.push(
    'collect_step_not_in_progress',
  );
}

if (
  row.validate_step_status !== 'pending'
) {
  contextErrors.push(
    'validate_step_not_pending',
  );
}

if (!isPlainObject(row.submitted_data)) {
  contextErrors.push(
    'submitted_data_not_object',
  );
}

if (!isPlainObject(row.normalized_data)) {
  contextErrors.push(
    'normalized_data_not_object',
  );
}

if (contextErrors.length > 0) {
  return [
    {
      json: {
        workflow: 'WF03',

        validation_decision:
          'invalid_authoritative_context',

        error_code:
          'authoritative_context_invalid',

        error_codes:
          contextErrors,

        case_id:
          isUuid(row.case_id)
            ? row.case_id
            : null,

        submission_id:
          isUuid(row.submission_id)
            ? row.submission_id
            : null,

        correlation_id:
          isUuid(row.correlation_id)
            ? row.correlation_id
            : null,

        client_response_key:
          'technical_failure',
      },
    },
  ];
}

const submittedData =
  row.submitted_data;

const persistedNormalizedData =
  row.normalized_data;

const identifier =
  normalizeIdentifierValue(
    submittedData
      .company_identifier_value ?? null,
  );

const recalculatedNormalizedData = {
  company_identifier_country:
    normalizeCountry(
      submittedData
        .company_identifier_country ?? null,
    ),

  company_identifier_type:
    normalizeIdentifierType(
      submittedData
        .company_identifier_type ?? null,
    ),

  company_identifier_value:
    identifier.visible,

  company_identifier_value_normalized:
    identifier.normalized,

  legal_name:
    normalizeCommonString(
      submittedData.legal_name ?? null,
    ),

  primary_contact_first_name:
    normalizeCommonString(
      submittedData
        .primary_contact_first_name ?? null,
    ),

  primary_contact_last_name:
    normalizeCommonString(
      submittedData
        .primary_contact_last_name ?? null,
    ),

  primary_contact_email:
    normalizeEmail(
      submittedData
        .primary_contact_email ?? null,
    ),

  primary_contact_phone:
    normalizePhone(
      submittedData
        .primary_contact_phone ?? null,
    ),
};

const normalizedFields =
  Object.keys(
    recalculatedNormalizedData,
  );

const persistedFields =
  Object.keys(
    persistedNormalizedData,
  );

const normalizedDataMatches =
  normalizedFields.length ===
    persistedFields.length &&
  normalizedFields.every(
    (fieldName) =>
      persistedNormalizedData[fieldName] ===
      recalculatedNormalizedData[fieldName],
  );

if (!normalizedDataMatches) {
  return [
    {
      json: {
        workflow: 'WF03',

        validation_decision:
          'invalid_authoritative_context',

        error_code:
          'persisted_normalization_mismatch',

        case_id:
          row.case_id,

        submission_id:
          row.submission_id,

        correlation_id:
          row.correlation_id,

        client_response_key:
          'technical_failure',
      },
    },
  ];
}

const validationErrors = [];

function addRequiredError(
  fieldName,
  value,
) {
  if (value === null) {
    validationErrors.push({
      field: fieldName,
      code: 'required',
    });

    return true;
  }

  return false;
}

const normalized =
  recalculatedNormalizedData;

if (
  !addRequiredError(
    'company_identifier_country',
    normalized
      .company_identifier_country,
  ) &&
  !/^[A-Z]{2}$/.test(
    normalized
      .company_identifier_country,
  )
) {
  validationErrors.push({
    field:
      'company_identifier_country',
    code: 'invalid_format',
  });
}

if (
  !addRequiredError(
    'company_identifier_type',
    normalized
      .company_identifier_type,
  ) &&
  !/^[a-z0-9][a-z0-9_-]{0,63}$/.test(
    normalized
      .company_identifier_type,
  )
) {
  validationErrors.push({
    field:
      'company_identifier_type',
    code: 'invalid_format',
  });
}

addRequiredError(
  'company_identifier_value',
  normalized
    .company_identifier_value,
);

if (
  !addRequiredError(
    'company_identifier_value_normalized',
    normalized
      .company_identifier_value_normalized,
  ) &&
  !/^[A-Z0-9]{2,64}$/.test(
    normalized
      .company_identifier_value_normalized,
  )
) {
  validationErrors.push({
    field:
      'company_identifier_value',
    code: 'invalid_format',
  });
}

addRequiredError(
  'legal_name',
  normalized.legal_name,
);

addRequiredError(
  'primary_contact_first_name',
  normalized
    .primary_contact_first_name,
);

addRequiredError(
  'primary_contact_last_name',
  normalized
    .primary_contact_last_name,
);

if (
  !addRequiredError(
    'primary_contact_email',
    normalized
      .primary_contact_email,
  ) &&
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/u.test(
    normalized
      .primary_contact_email,
  )
) {
  validationErrors.push({
    field:
      'primary_contact_email',
    code: 'invalid_format',
  });
}

if (
  !addRequiredError(
    'primary_contact_phone',
    normalized
      .primary_contact_phone,
  ) &&
  !/^\+[1-9][0-9]{7,14}$/.test(
    normalized
      .primary_contact_phone,
  )
) {
  validationErrors.push({
    field:
      'primary_contact_phone',
    code: 'invalid_format',
  });
}

const validationPassed =
  validationErrors.length === 0;

return [
  {
    json: {
      workflow: 'WF03',

      validation_decision:
        validationPassed
          ? 'validation_passed'
          : 'validation_failed',

      case_id:
        row.case_id,

      correlation_id:
        row.correlation_id,

      submission_id:
        row.submission_id,

      submission_sequence:
        submissionSequence,

      token_id:
        row.token_id,

      collect_step_id:
        row.collect_step_id,

      collect_step_attempt_count:
        Number(
          row.collect_step_attempt_count,
        ),

      validate_step_id:
        row.validate_step_id,

      validate_step_attempt_count:
        Number(
          row.validate_step_attempt_count,
        ),

      normalized_data:
        normalized,

      validation_errors:
        validationErrors,

      client_response_key:
        validationPassed
          ? 'submission_accepted'
          : 'submission_requires_correction',
    },
  },
];

const items = $input.all();

function isPlainObject(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    !Array.isArray(value)
  );
}

function isUuid(value) {
  return (
    typeof value === 'string' &&
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i
      .test(value)
  );
}

function normalizeInvocationMode(value) {
  if (
    value === 'form_submission' ||
    value === 'recovery'
  ) {
    return value;
  }

  return null;
}

function buildInvalidResult(
  errorCode,
  row = {},
  inputContext = {},
) {
  return [
    {
      json: {
        workflow: 'WF03',

        invocation_mode:
          normalizeInvocationMode(
            inputContext.invocation_mode,
          ),

        finalization_decision:
          'invalid_finalization_result',

        error_code:
          errorCode,

        finalization_outcome:
          typeof row.finalization_outcome === 'string'
            ? row.finalization_outcome
            : null,

        case_id:
          isUuid(inputContext.case_id)
            ? inputContext.case_id
            : null,

        submission_id:
          isUuid(inputContext.submission_id)
            ? inputContext.submission_id
            : null,

        correlation_id:
          isUuid(inputContext.correlation_id)
            ? inputContext.correlation_id
            : null,

        client_response_key:
          'technical_failure',
      },
    },
  ];
}

if (items.length !== 1) {
  return buildInvalidResult(
    'validation_finalization_item_count_invalid',
  );
}

const row = items[0].json ?? {};

const inputContext =
  isPlainObject(row.input_context)
    ? row.input_context
    : {};

