  null;

let recoveryResult;
let completed;

if (continuationKind === 'approval_dispatch') {
  recoveryResult =
    'approval_dispatch_started';

  completed = true;

} else if (
  continuationKind === 'correction_dispatch' &&
  input.correction_decision === 'correction_ready'
) {
  recoveryResult =
    'correction_delivery_confirmed';

  completed = true;

} else if (
  continuationKind === 'correction_dispatch' &&
  input.correction_decision === 'correction_scheduled'
) {
  recoveryResult =
    'correction_delivery_scheduled';

  completed = true;

} else if (
  input.error_class !== undefined ||
  input.error_code !== undefined ||
  input.source_variant === 'explicit_internal'
) {
  recoveryResult =
    'technical_failure_recorded';

  completed = false;

} else {
  throw new Error(
    'WF03 received an unsupported recovery completion state',
  );
}

return {
  json: {
    workflow: 'WF03',

    invocation_mode:
      'recovery',

    recovery_result:
      recoveryResult,

    case_id:
      input.case_id ?? null,

    correlation_id:
      input.correlation_id ?? null,

    submission_id:
      input.submission_id ?? null,

    wf02_result:
      input.wf02_result ??
      errorDetails.wf02_result ??
      null,

    error_class:
      input.error_class ?? null,

    error_code:
      input.error_code ?? null,

    retryable:
      typeof input.retryable === 'boolean'
        ? input.retryable
        : null,

    completed:
      completed,
  },
};
